import time
import logging
import aiosqlite
import numpy as np
from collections import defaultdict
from itertools import combinations
from sklearn.metrics.pairwise import cosine_similarity
from sklearn.preprocessing import normalize

from .config import SearchRecConfig

logger = logging.getLogger(__name__)


async def load_sessions(db_path: str) -> dict[str, list[str]]:
    sessions = defaultdict(list)
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute(
            "SELECT session_id, item_id FROM click_events ORDER BY session_id, ts ASC"
        )
        rows = list(await cursor.fetchall())
    for row in rows:
        sessions[row["session_id"]].append(row["item_id"])
    logger.info(f"Loaded {len(rows)} clicks across {len(sessions)} sessions")
    return dict(sessions)


def build_coclick_matrix(sessions: dict[str, list[str]]) -> tuple[dict, np.ndarray]:
    all_items = sorted({item for items in sessions.values() for item in items})
    item_index = {item: idx for idx, item in enumerate(all_items)}
    n = len(all_items)

    if n == 0:
        return item_index, np.zeros((0, 0))

    matrix = np.zeros((n, n), dtype=np.float32)
    for session_items in sessions.values():
        unique_items = list(dict.fromkeys(session_items))[:10]
        for item_a, item_b in combinations(unique_items, 2):
            i, j = item_index[item_a], item_index[item_b]
            matrix[i, j] += 1
            matrix[j, i] += 1

    logger.info(f"Built {n}x{n} co-click matrix")
    return item_index, matrix


def compute_similarities(
    item_index: dict[str, int],
    matrix: np.ndarray,
    top_n: int,
    min_coclick: int,
) -> dict[str, list[tuple[str, float]]]:
    # Pairs below min_coclick are zeroed before normalisation so single-session
    # flukes don't influence similarity scores.
    if matrix.size == 0:
        return {}

    filtered = matrix.copy()
    filtered[filtered < min_coclick] = 0.0
    normed = normalize(filtered, norm="l2")
    sim_matrix = cosine_similarity(normed)
    index_item = {idx: item for item, idx in item_index.items()}

    results = {}
    for item_id, idx in item_index.items():
        scores = sim_matrix[idx]
        ranked = sorted(
            [(index_item[j], float(scores[j])) for j in range(len(scores)) if j != idx],
            key=lambda x: x[1],
            reverse=True,
        )
        results[item_id] = [(sim_id, score) for sim_id, score in ranked[:top_n] if score > 0.0]

    return results


async def save_similarities(db_path: str, similarities: dict[str, list[tuple[str, float]]]) -> None:
    if not similarities:
        logger.warning("No similarities to save — skipping")
        return

    now = int(time.time() * 1000)
    rows = [
        (item_id, similar_id, score, now)
        for item_id, neighbours in similarities.items()
        for similar_id, score in neighbours
    ]

    async with aiosqlite.connect(db_path) as db:
        await db.execute("DELETE FROM item_similarities")
        await db.executemany(
            "INSERT INTO item_similarities (item_id, similar_id, score, updated_at) VALUES (?, ?, ?, ?)",
            rows,
        )
        await db.commit()

    logger.info(f"Saved {len(rows)} similarity pairs to DB")


async def get_recommendations(db_path: str, item_id: str, limit: int) -> list[dict]:
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute(
            """
            SELECT similar_id, score
            FROM item_similarities
            WHERE item_id = ?
            ORDER BY score DESC
            LIMIT ?
            """,
            (item_id, limit),
        )
        rows = await cursor.fetchall()
    return [{"item_id": r["similar_id"], "score": r["score"]} for r in rows]


async def retrain(config: SearchRecConfig) -> dict:
    logger.info("Starting recommendation retrain...")
    sessions = await load_sessions(config.db_path)

    if not sessions:
        return {"status": "skipped", "reason": "no data"}

    if len(sessions) < config.min_sessions_to_retrain:
        logger.warning(f"Only {len(sessions)} sessions — need {config.min_sessions_to_retrain} to retrain")
        return {
            "status": "skipped",
            "reason": f"need at least {config.min_sessions_to_retrain} sessions, got {len(sessions)}",
        }

    item_index, matrix = build_coclick_matrix(sessions)
    similarities = compute_similarities(item_index, matrix, config.top_n, config.min_coclick)
    await save_similarities(config.db_path, similarities)

    logger.info("Retrain complete")
    return {
        "status": "ok",
        "sessions": len(sessions),
        "items": len(item_index),
        "pairs": sum(len(v) for v in similarities.values()),
    }
